import sys, heapq

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    g = data[1:1 + n]
    for i in range(n):
        for j in range(n):
            ch = g[i][j]
            if ch == 'S': s = (i, j)
            elif ch == 'T': t = (i, j)
            elif ch == 'C': c = (i, j)
    cr, cc = c
    best = [[-1] * n for _ in range(n)]
    si, sj = s
    d0 = abs(si - cr) + abs(sj - cc)
    best[si][sj] = d0
    heap = [(-d0, si, sj)]
    while heap:
        nd, i, j = heapq.heappop(heap)
        nd = -nd
        if nd < best[i][j]:
            continue
        if (i, j) == t:
            break
        for ni, nj in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= ni < n and 0 <= nj < n and g[ni][nj] != '#':
                v = min(nd, abs(ni - cr) + abs(nj - cc))
                if v > best[ni][nj]:
                    best[ni][nj] = v
                    heapq.heappush(heap, (-v, ni, nj))
    print(best[t[0]][t[1]])

main()

